<template><div><div class="admin-page-head"><div><h1>Пользователи</h1><p>Клиенты, бронирования и история активности.</p></div></div><div class="filters"><input v-model="search" class="input" placeholder="Имя, email, телефон…" @keyup.enter="load"><select v-model="status" class="select"><option value="">Все статусы</option><option value="active">Активные</option><option value="suspended">Заблокированные</option></select><select v-model="role" class="select"><option value="">Все роли</option><option value="user">User</option><option value="admin">Admin</option><option value="manager">Manager</option><option value="editor">Editor</option></select><button class="btn primary" @click="load">Найти</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Пользователь</th><th>Контакты</th><th>Роль</th><th>Брони</th><th>Потрачено</th><th>Регистрация</th><th></th></tr></thead><tbody><tr v-for="u in data.items" :key="u.id"><td><b>{{ u.firstName }} {{ u.lastName||'' }}</b><div class="muted">{{ u.id }}</div></td><td>{{ u.email||u.phone||'—' }}</td><td><span class="pill">{{ u.role }}</span></td><td>{{ u.bookingsCount }}</td><td>{{ money(u.totalSpent) }}</td><td>{{ date(u.createdAt) }}</td><td><NuxtLink class="btn" :to="`/admin/users/${u.id}`">Открыть</NuxtLink></td></tr></tbody></table><div v-if="!data.items.length" class="empty">Пользователи не найдены</div></div></div></template>
<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin'})
const api=useApi();const search=ref('');const status=ref('');const role=ref('');const data=ref<any>({items:[]});const load=async()=>{data.value=await api('/api/admin/users',{query:{search:search.value,status:status.value,role:role.value,limit:50}})};await load();const money=(v:number)=>new Intl.NumberFormat('ru-RU').format(v||0)+' ₽';const date=(v:string)=>new Date(v).toLocaleDateString('ru-RU')
</script>
